STYLESHEET = '\n            * {\n                font-family: "Segoe UI";\n            }\n\n            #Root, #Content, QDialog {\n                background: #080c12;\n            }\n\n            QScrollArea {\n                background: transparent;\n                border: none;\n            }\n\n            QScrollArea > QWidget > QWidget {\n                background: transparent;\n            }\n\n            QScrollBar:vertical {\n                background: transparent;\n                width: 10px;\n                margin: 2px;\n            }\n\n            QScrollBar::handle:vertical {\n                background: #293342;\n                min-height: 34px;\n                border-radius: 5px;\n            }\n\n            QScrollBar::handle:vertical:hover {\n                background: #3b4a60;\n            }\n\n            QScrollBar::add-line:vertical,\n            QScrollBar::sub-line:vertical,\n            QScrollBar::add-page:vertical,\n            QScrollBar::sub-page:vertical {\n                background: transparent;\n                height: 0px;\n            }\n\n            #Sidebar {\n                background: #0d121a;\n                border-right: 1px solid #1d2734;\n            }\n\n            #BrandMark {\n                color: #eaf3ff;\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:1,\n                    stop:0 #377cf4, stop:1 #694ee8);\n                border: 1px solid #5889f4;\n                border-radius: 12px;\n                font-size: 13px;\n                font-weight: 900;\n            }\n\n            #Logo {\n                color: #f7f9fc;\n                font-size: 20px;\n                font-weight: 800;\n            }\n\n            #SidebarVersion {\n                color: #58687d;\n                font-size: 8px;\n                font-weight: 700;\n            }\n\n            #SidebarSection {\n                color: #4f6076;\n                font-size: 9px;\n                font-weight: 800;\n                padding: 2px 10px 5px 10px;\n            }\n\n            NavButton {\n                background: transparent;\n                color: #8493a7;\n                border: 1px solid transparent;\n                border-radius: 11px;\n                text-align: left;\n                padding-left: 14px;\n                font-size: 12px;\n                font-weight: 650;\n            }\n\n            NavButton:hover {\n                background: #121a25;\n                color: #dbe8f8;\n                border: 1px solid #1d2a39;\n            }\n\n            NavButton:checked {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n                    stop:0 #172741, stop:1 #101926);\n                color: #8db8ff;\n                border: 1px solid #29466d;\n            }\n\n            #PrivacyCard {\n                background: #0f1719;\n                border: 1px solid #1d3431;\n                border-radius: 12px;\n            }\n\n            #LocalBadge {\n                color: #5dd9a2;\n                font-size: 9px;\n                font-weight: 850;\n            }\n\n            #PrivacyText {\n                color: #5d6c79;\n                font-size: 9px;\n                line-height: 1.35;\n            }\n\n            #TopTitle {\n                color: #8899ad;\n                font-size: 12px;\n                font-weight: 650;\n            }\n\n            #FactsBadge {\n                color: #5fdba4;\n                background: #0f1d1a;\n                border: 1px solid #1f4437;\n                border-radius: 9px;\n                padding: 7px 11px;\n                font-size: 9px;\n                font-weight: 800;\n            }\n\n            #PageKicker {\n                color: #4779bf;\n                font-size: 9px;\n                font-weight: 850;\n                letter-spacing: 1px;\n            }\n\n            #PageTitle {\n                color: #f5f8fc;\n                font-size: 31px;\n                font-weight: 850;\n            }\n\n            #PageSubtitle {\n                color: #718095;\n                font-size: 13px;\n            }\n\n            #SecondaryButton,\n            #SecondaryActionButton {\n                background: #111822;\n                color: #b8c4d3;\n                border: 1px solid #263243;\n                border-radius: 9px;\n                padding: 9px 13px;\n                font-weight: 650;\n            }\n\n            #SecondaryButton:hover,\n            #SecondaryActionButton:hover {\n                background: #182231;\n                color: #f0f5fb;\n                border: 1px solid #354965;\n            }\n\n            #SafetyButton {\n                background: #201912;\n                color: #e1b675;\n                border: 1px solid #49341d;\n                border-radius: 9px;\n                padding: 9px 13px;\n                font-weight: 650;\n            }\n\n            #SafetyButton:hover {\n                background: #2a2116;\n                border: 1px solid #65502d;\n            }\n\n            #SummaryBanner {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:1,\n                    stop:0 #111a27, stop:0.55 #101722, stop:1 #111927);\n                border: 1px solid #263d59;\n                border-radius: 18px;\n            }\n\n            #SummaryKicker {\n                color: #6298e7;\n                font-size: 9px;\n                font-weight: 850;\n            }\n\n            #SummaryTitle {\n                color: #f4f8fd;\n                font-size: 21px;\n                font-weight: 850;\n            }\n\n            #SummaryText {\n                color: #8a9bb0;\n                font-size: 11px;\n            }\n\n            #SummaryMeta {\n                color: #566a82;\n                font-size: 9px;\n                font-weight: 750;\n            }\n\n            #SummaryStats {\n                background: #0c121b;\n                border: 1px solid #1e2a39;\n                border-radius: 13px;\n                min-width: 170px;\n            }\n\n            #SummaryMiniStat {\n                background: #101721;\n                border: 1px solid #1d2937;\n                border-radius: 9px;\n            }\n\n            #SummaryMiniLabel {\n                color: #7c8da3;\n                font-size: 10px;\n                font-weight: 650;\n            }\n\n            #SummaryMiniValue {\n                color: #f3f6fa;\n                font-size: 14px;\n                font-weight: 850;\n            }\n\n            #SummaryMiniDot[state="good"] { color: #55d69a; }\n            #SummaryMiniDot[state="warning"] { color: #f2a45e; }\n            #SummaryMiniDot[state="neutral"] { color: #61758d; }\n\n            #HeroCard,\n            #DoctorHero {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n                    stop:0 #121a26, stop:0.7 #101721, stop:1 #141a24);\n                border: 1px solid #29384b;\n                border-radius: 16px;\n            }\n\n            #ScanIcon,\n            #DoctorIcon {\n                color: #8fc0ff;\n                background: #132642;\n                border: 1px solid #2f5483;\n                border-radius: 16px;\n                font-size: 11px;\n                font-weight: 900;\n            }\n\n            #HeroKicker {\n                color: #4e82c9;\n                font-size: 8px;\n                font-weight: 850;\n            }\n\n            #HeroTitle,\n            #ActionTitle {\n                color: #f4f7fb;\n                font-size: 18px;\n                font-weight: 800;\n            }\n\n            #HeroText,\n            #ActionText {\n                color: #7b8b9f;\n                font-size: 11px;\n            }\n\n            #HeroChip {\n                color: #768da8;\n                background: #111b28;\n                border: 1px solid #27384d;\n                border-radius: 7px;\n                padding: 5px 8px;\n                font-size: 8px;\n                font-weight: 850;\n            }\n\n            #PrimaryButton {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n                    stop:0 #377df5, stop:1 #5a69f2);\n                color: white;\n                border: 1px solid #638df4;\n                border-radius: 10px;\n                padding: 11px 18px;\n                font-size: 12px;\n                font-weight: 800;\n                min-width: 118px;\n            }\n\n            #PrimaryButton:hover {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n                    stop:0 #4c8dfb, stop:1 #6d79fa);\n                border: 1px solid #8aabff;\n            }\n\n            #PrimaryButton:pressed {\n                background: #315fc6;\n            }\n\n            #PrimaryButton:disabled {\n                background: #182337;\n                color: #5c6b80;\n                border: 1px solid #253349;\n            }\n\n            #DashboardSectionTitle {\n                color: #546a84;\n                font-size: 9px;\n                font-weight: 900;\n                letter-spacing: 1px;\n                padding-top: 4px;\n            }\n\n            #StatCard {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:1,\n                    stop:0 #111821, stop:1 #0e141c);\n                border: 1px solid #222d3a;\n                border-radius: 15px;\n                min-height: 140px;\n            }\n\n            #StatCard[state="good"] { border: 1px solid #245043; }\n            #StatCard[state="minor"] { border: 1px solid #56462a; }\n            #StatCard[state="warning"] { border: 1px solid #654123; }\n            #StatCard[state="danger"] { border: 1px solid #68323a; }\n            #StatCard[state="unavailable"] { border: 1px solid #273343; }\n\n            #MetricSymbol {\n                color: #9bb7d9;\n                background: #172233;\n                border: 1px solid #273b55;\n                border-radius: 10px;\n                font-size: 12px;\n                font-weight: 900;\n            }\n\n            #MetricSymbol[state="good"] {\n                color: #64dda5;\n                background: #10271f;\n                border: 1px solid #24513e;\n            }\n\n            #MetricSymbol[state="minor"],\n            #MetricSymbol[state="warning"] {\n                color: #efb46b;\n                background: #2a2114;\n                border: 1px solid #5a4222;\n            }\n\n            #MetricSymbol[state="danger"] {\n                color: #ff7d85;\n                background: #2c171b;\n                border: 1px solid #66303a;\n            }\n\n            #StatTitle {\n                color: #dfe7f0;\n                font-size: 12px;\n                font-weight: 750;\n            }\n\n            #StatKicker {\n                color: #516278;\n                font-size: 7px;\n                font-weight: 850;\n            }\n\n            #StatValue {\n                color: #f6f8fb;\n                font-size: 23px;\n                font-weight: 850;\n                padding-top: 2px;\n            }\n\n            #StatSubtitle {\n                color: #708196;\n                font-size: 9px;\n            }\n\n            #StatBadge {\n                background: #18212c;\n                color: #7e8da0;\n                border: 1px solid #263343;\n                border-radius: 7px;\n                padding: 4px 8px;\n                font-size: 7px;\n                font-weight: 900;\n            }\n\n            #StatBadge[state="good"] {\n                background: #10261e;\n                color: #61dca2;\n                border: 1px solid #24503e;\n            }\n\n            #StatBadge[state="minor"],\n            #StatBadge[state="warning"] {\n                background: #2a2114;\n                color: #efb16a;\n                border: 1px solid #54401f;\n            }\n\n            #StatBadge[state="danger"] {\n                background: #2b171b;\n                color: #ff7c84;\n                border: 1px solid #5f3037;\n            }\n\n            #StatBadge[state="unavailable"] {\n                background: #151d27;\n                color: #718196;\n                border: 1px solid #283545;\n            }\n\n            #MetricMeter {\n                min-height: 5px;\n                max-height: 5px;\n                background: #1a2330;\n                border: none;\n                border-radius: 2px;\n            }\n\n            #MetricMeter::chunk {\n                background: #6088c1;\n                border-radius: 2px;\n            }\n\n            #MetricMeter[state="good"]::chunk { background: #47c98f; }\n            #MetricMeter[state="minor"]::chunk { background: #d9b157; }\n            #MetricMeter[state="warning"]::chunk { background: #e8944b; }\n            #MetricMeter[state="danger"]::chunk { background: #eb626f; }\n            #MetricMeter[state="unavailable"]::chunk { background: #526277; }\n\n            #CollapsibleSection {\n                background: transparent;\n                border: 1px solid #202b38;\n                border-radius: 14px;\n            }\n\n            #CollapsibleHeader {\n                background: #0f151e;\n                border-radius: 13px;\n            }\n\n            #CollapsibleTitle {\n                color: #dbe4ef;\n                font-size: 13px;\n                font-weight: 750;\n            }\n\n            #CollapsibleSubtitle {\n                color: #617186;\n                font-size: 9px;\n            }\n\n            #CollapseToggle {\n                background: #162131;\n                color: #80adf4;\n                border: 1px solid #2b405b;\n                border-radius: 10px;\n                font-size: 22px;\n                font-weight: 700;\n            }\n\n            #CollapseToggle:hover {\n                background: #1d2e44;\n                color: #b2d2ff;\n                border: 1px solid #416493;\n            }\n\n            #CollapsibleContent {\n                background: #0c1219;\n                border-top: 1px solid #1b2633;\n            }\n\n            #InfoValueCard {\n                background: #101721;\n                border: 1px solid #202c3a;\n                border-radius: 11px;\n                min-height: 78px;\n            }\n\n            #InfoValueTitle {\n                color: #52739c;\n                font-size: 8px;\n                font-weight: 850;\n            }\n\n            #InfoValueText {\n                color: #dce5ef;\n                font-size: 10px;\n                font-weight: 650;\n            }\n\n            #ResultPanel {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:1,\n                    stop:0 #0f151e, stop:1 #0d131a);\n                border: 1px solid #243141;\n                border-radius: 17px;\n            }\n\n            #ResultKicker {\n                color: #557fae;\n                font-size: 8px;\n                font-weight: 900;\n            }\n\n            #ResultTitle {\n                color: #f3f7fc;\n                font-size: 21px;\n                font-weight: 850;\n            }\n\n            #ResultExplanation {\n                color: #78899d;\n                font-size: 11px;\n            }\n\n            #ResultScoreBox {\n                background: #0b1119;\n                border: 1px solid #233144;\n                border-radius: 13px;\n                min-width: 126px;\n            }\n\n            #ScoreCaption {\n                color: #50647e;\n                font-size: 7px;\n                font-weight: 900;\n            }\n\n            #ResultScore {\n                color: #f6f8fc;\n                font-size: 27px;\n                font-weight: 900;\n            }\n\n            #StatusBadge {\n                color: #8494a8;\n                background: #151e29;\n                border: 1px solid #273545;\n                border-radius: 7px;\n                padding: 4px 8px;\n                font-size: 7px;\n                font-weight: 900;\n            }\n\n            #StatusBadge[state="good"] {\n                color: #67dda5;\n                background: #10261e;\n                border: 1px solid #24503e;\n            }\n\n            #StatusBadge[state="minor"] {\n                color: #e1c36d;\n                background: #282313;\n                border: 1px solid #4e4320;\n            }\n\n            #StatusBadge[state="warning"] {\n                color: #eda05a;\n                background: #2b1f14;\n                border: 1px solid #593a20;\n            }\n\n            #StatusBadge[state="danger"] {\n                color: #ff7a83;\n                background: #2b171b;\n                border: 1px solid #5e3037;\n            }\n\n            #PrimaryIssueCard {\n                background: #101821;\n                border: 1px solid #223244;\n                border-radius: 13px;\n            }\n\n            #PrimaryIssueCard[active="true"] {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n                    stop:0 #211916, stop:1 #14161b);\n                border: 1px solid #66462a;\n            }\n\n            #PrimaryEyebrow {\n                color: #5f87b8;\n                font-size: 8px;\n                font-weight: 900;\n            }\n\n            #PrimarySignal {\n                color: #4fd39a;\n                font-size: 9px;\n            }\n\n            #PrimaryIssueCard[active="true"] #PrimarySignal {\n                color: #f0a05a;\n            }\n\n            #PrimaryIssueText {\n                color: #eef3f9;\n                font-size: 15px;\n                font-weight: 800;\n            }\n\n            #PrimaryWhyTitle {\n                color: #75879c;\n                font-size: 9px;\n                font-weight: 750;\n            }\n\n            #PrimaryWhyText {\n                color: #9aa8b8;\n                font-size: 10px;\n            }\n\n            #RecommendationPanel {\n                background: #0d141d;\n                border: 1px solid #202d3d;\n                border-radius: 13px;\n            }\n\n            #RecommendationTitle {\n                color: #e4ebf3;\n                font-size: 13px;\n                font-weight: 800;\n            }\n\n            #RecommendationKicker {\n                color: #4f6d91;\n                font-size: 7px;\n                font-weight: 900;\n            }\n\n            #RecommendationStep {\n                background: #111a25;\n                border: 1px solid #1f2d3d;\n                border-radius: 10px;\n            }\n\n            #RecommendationNumber {\n                color: #bcd6ff;\n                background: #193052;\n                border: 1px solid #2e5689;\n                border-radius: 14px;\n                font-size: 10px;\n                font-weight: 900;\n            }\n\n            #RecommendationText {\n                color: #aebbc9;\n                font-size: 10px;\n            }\n\n            #RecommendationEmpty {\n                color: #6f8299;\n                font-size: 10px;\n                padding: 5px 0px;\n            }\n\n            #SectionCard {\n                background: #101720;\n                border: 1px solid #202c39;\n                border-radius: 10px;\n            }\n\n            #SectionTitle {\n                color: #d6e0ea;\n                font-size: 12px;\n                font-weight: 800;\n            }\n\n            #SectionText {\n                color: #8f9dae;\n                font-size: 10px;\n            }\n\n            #ResultNote {\n                color: #536579;\n                font-size: 9px;\n            }\n\n            #ScanProgress {\n                background: #121a24;\n                border: 1px solid #1e2a38;\n                border-radius: 4px;\n                min-height: 7px;\n                max-height: 7px;\n            }\n\n            #ScanProgress::chunk {\n                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n                    stop:0 #397ff7, stop:0.5 #6e6cf5, stop:1 #39b9e8);\n                border-radius: 3px;\n            }\n\n            #DialogTitle {\n                color: #f4f7fb;\n                font-size: 23px;\n                font-weight: 850;\n            }\n\n            #DialogSubtitle {\n                color: #76879b;\n                font-size: 11px;\n            }\n\n            #DialogCard {\n                background: #111821;\n                border: 1px solid #22303f;\n                border-radius: 11px;\n            }\n\n            #DialogWarningCard {\n                background: #201914;\n                border: 1px solid #543b20;\n                border-radius: 11px;\n            }\n\n            #DialogCardTitle {\n                color: #e9eff6;\n                font-size: 12px;\n                font-weight: 800;\n            }\n\n            #DialogCardText {\n                color: #9aa8b7;\n                font-size: 10px;\n            }\n\n            #DialogCloseX {\n                background: #121a24;\n                color: #9aa9ba;\n                border: 1px solid #293646;\n                border-radius: 9px;\n                font-size: 20px;\n            }\n\n            #DialogCloseX:hover {\n                background: #1a2533;\n                color: white;\n            }\n\n            #DialogCloseButton {\n                background: #377df5;\n                color: white;\n                border: 1px solid #5c8cf4;\n                border-radius: 9px;\n                padding: 10px 18px;\n                font-weight: 750;\n            }\n\n            #DialogCloseButton:hover {\n                background: #4a8df9;\n            }\n            '
